observed_transformations.new:
const { child, control } = spawnSupervisor();

const probeStarted = performance.now();
const probeEvents: unknown[] = [];
const probeStreamState = () => Object.fromEntries(Object.entries({stdin:child.stdin,stdout:child.stdout,stderr:child.stderr,control}).map(([name,stream]) => [name, { closed:stream.closed, destroyed:stream.destroyed, readableEnded:stream.readableEnded, writableEnded:stream.writableEnded, readableLength:stream.readableLength, fd:(stream as any)._handle?.fd }]));
const probeRecord = (event:string, fields:object={}) => { probeEvents.push({tMs:performance.now()-probeStarted,event,...fields}); };
const probe = {child,control,events:probeEvents, snapshot:probeStreamState, record:probeRecord};
((globalThis as any).__bootstrapHandles ??= []).push(probe);
probeRecord('spawn-returned',{pid:child.pid,streams:probeStreamState()});
for (const [name,stream] of Object.entries({stdin:child.stdin,stdout:child.stdout,stderr:child.stderr,control})) {
  for (const event of ['end','close','finish','error']) stream.on(event,(error?:Error) => probeRecord(name+'.'+event,{error:error?.message,streams:probeStreamState()}));
}
child.on('exit',(code:number|null,signal:string|null) => probeRecord('child.exit',{code,signal,streams:probeStreamState()}));
child.on('close',() => probeRecord('child.close',{streams:probeStreamState()}));
child.on('error',(error:Error) => probeRecord('child.error',{error:error.message}));
control.on('data',(chunk:Buffer) => probeRecord('control.data',{text:chunk.toString()}));
